'use strict';
let on = false;
function buildCss(s) {
  const n = Math.min(20, Math.max(1, Number(s.amount) || 6));
  return '[id^="message-content-"],[id^="message-username-"],img[class*="avatar"]{filter:blur(' + n + 'px);transition:filter .12s;}\n' +
         '[id^="message-content-"]:hover,[id^="message-username-"]:hover,img[class*="avatar"]:hover{filter:none;}';
}
function start() {
  const s = api.settings.all();
  on = !!s.startOn;
  if (on) api.css.set(buildCss(s));
  api.hotkey('ctrl+alt+' + String(s.key || 'b').toLowerCase().slice(0, 1), () => {
    on = !on;
    if (on) api.css.set(buildCss(s)); else api.css.remove();
    api.toast(on ? 'Privacy blur on' : 'Privacy blur off');
  });
}
function stop() { api.css.remove(); on = false; }
module.exports = { start, stop, buildCss };
